// Generates db/seed/002_seed.sql from frontend/src/test-utils/grc-fixture.ts. Fictional demo data. Do not edit the SQL by hand.
// Run: node --experimental-strip-types db/scripts/seed-db.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { basename, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as g from '../../frontend/src/test-utils/grc-fixture.ts';

const root = fileURLToPath(new URL('../..', import.meta.url));
const q = (v) => (v == null ? 'NULL' : `'${String(v).replaceAll("'", "''")}'`);
const insert = (table, cols, rows) =>
  `INSERT INTO ${table} (${cols.join(', ')}) VALUES\n${rows.map((r) => `(${r.map(q).join(', ')})`).join(',\n')}\nON CONFLICT DO NOTHING;\n`;

const assets = insert('assets',
  ['id', 'name', 'type', 'site', 'sector', 'purdue_level', 'zone', 'vendor', 'model', 'firmware', 'ip_address', 'criticality', 'owner', 'last_reviewed', 'status'],
  g.assets.map((a) => [a.id, a.name, a.type, a.site, a.sector, a.purdueLevel, a.zone, a.vendor, a.model, a.firmware, a.ipAddress, a.criticality, a.owner, a.lastReviewed, a.status]));

const documents = insert('documents',
  ['id', 'title', 'type', 'tlp', 'status', 'owner', 'approver', 'next_review'],
  g.documents.map((d) => [d.id, d.title, d.type, d.tlp, d.status, d.owner, d.approver, d.nextReview]));

const versionRows = g.documents.flatMap((d) => d.versions.map((v) => {
  const f = v.file;
  const bytes = f ? readFileSync(join(root, 'db', 'seed-files', basename(f.url))) : null;
  return [d.id, v.version, v.date, v.author, v.summary, v.approvedBy, f?.name, f?.mime, bytes?.length,
    bytes?.toString('base64')];
}));
const versions = insert('document_versions',
  ['document_id', 'version', 'date', 'author', 'summary', 'approved_by', 'file_name', 'mime_type', 'size_bytes', 'content_base64'],
  versionRows);

const evidence = insert('evidence_links', ['id', 'subcategory_id', 'document_id', 'asset_id', 'note'],
  g.evidenceLinks.map((e, i) => [`EV-${String(i + 1).padStart(4, '0')}`, e.subcategoryId, e.documentId, e.assetId, e.note]));

const assetDocs = insert('asset_document_links', ['asset_id', 'document_id'],
  g.assetDocLinks.map((l) => [l.assetId, l.documentId]));

const audit = insert('audit_events', ['id', 'at', 'actor', 'action', 'object_type', 'object_id', 'summary', 'changes'],
  g.auditEvents.map((e) => [e.id, e.at, e.actor, e.action, e.objectType, e.objectId, e.summary, e.changes && JSON.stringify(e.changes)]));

const header = '-- Generated by db/scripts/seed-db.mjs from frontend/src/test-utils/grc-fixture.ts. Fictional simulation data. Do not edit by hand.\nBEGIN;\n\n';
writeFileSync(join(root, 'db', 'seed', '002_seed.sql'),
  header + [assets, documents, versions, evidence, assetDocs, audit].join('\n') + '\nCOMMIT;\n');

if (process.argv.includes('--update-demo')) {
  const priorTitles = g.documents.map((d) => d.title); // Exact current localized demo snapshot only; unknown edits refuse the migration.

  const oldFiles = [
    'installation-ot-security-policy.pdf',
    'installation-register.xlsx',
    'halvard-water-network-diagram.pdf',
    'incident-response-plan.pdf',
    'base-ot-risk-assessment.pdf',
    'personnel-roster.xlsx',
    'equipment-register.xlsx',
    'ot-audit-report.pdf',
  ];
  const expectedTitles = priorTitles.map((title, i) => `IF NOT EXISTS (SELECT 1 FROM documents WHERE id = 'DOC-${String(i + 1).padStart(4, '0')}' AND title = ${q(title)}) THEN RAISE EXCEPTION 'demo document baseline mismatch: DOC-${String(i + 1).padStart(4, '0')}'; END IF;`).join('\n  ');
  const expectedFiles = oldFiles.map((name) => `IF NOT EXISTS (SELECT 1 FROM document_versions WHERE file_name = ${q(name)}) THEN RAISE EXCEPTION 'demo file baseline mismatch: ${name}'; END IF;`).join('\n  ');
  const updates = [
    ...g.documents.map((d) => `UPDATE documents SET title=${q(d.title)}, owner=${q(d.owner)}, approver=${q(d.approver)} WHERE id=${q(d.id)};`),
    ...versionRows.map((r) => `UPDATE document_versions SET author=${q(r[3])}, summary=${q(r[4])}, approved_by=${q(r[5])}${r[9] ? `, size_bytes=${q(r[8])}, content_base64=${q(r[9])}` : ''} WHERE document_id=${q(r[0])} AND version=${q(r[1])};`),
  ].join('\n');
  const migration = `-- Controlled localization update; refuses unknown demo DB state. Does not mutate audit_events or delete rows.\nBEGIN;\nDO $$ BEGIN\n  IF (SELECT count(*) FROM documents) <> 16 OR (SELECT count(*) FROM document_versions) <> 42 OR (SELECT count(*) FROM document_versions WHERE file_name IS NOT NULL) <> 8 THEN RAISE EXCEPTION 'demo DB counts differ; refusing update'; END IF;\n  IF md5((SELECT string_agg(concat_ws('|',id,title,owner,approver,status,next_review::text), E'\\n' ORDER BY id) FROM documents)) NOT IN ('54b176517e89d0a29bd2d143ff00a2b6','2a88b2f5934e2c7349c5ed34f505b3e2') THEN RAISE EXCEPTION 'document metadata baseline differs; refusing update'; END IF;\n  IF md5((SELECT string_agg(concat_ws('|',document_id,version,author,summary,coalesce(approved_by,''),coalesce(file_name,''),coalesce(size_bytes::text,'')), E'\\n' ORDER BY document_id,version) FROM document_versions)) NOT IN ('aaf6f142d0beec5134aeaec8a00c24d4','3ccde291e2a67df78b44b40b0a447a7a') THEN RAISE EXCEPTION 'version metadata baseline differs; refusing update'; END IF;\n  ${expectedTitles}\n  ${expectedFiles}\nEND $$;\n${updates}\nCOMMIT;\n`;
  writeFileSync(join(root, 'db', 'scripts', 'localize-demo-docs.sql'), migration);
  console.log('wrote controlled db/scripts/localize-demo-docs.sql');
}
console.log(`wrote db/seed/002_seed.sql: ${versionRows.length} versions, ${versionRows.filter((r) => r[8]).length} files`);
